char *convert(char *s, int numRows) {
  int len;
  int i, j, k = 0;
  char *p;
  int step, up;

  if (!s || !*s || numRows == 1) return s;

  len = strlen(s);
  p = malloc((len + 1) * sizeof(char));
  //assert(p);

  step = (numRows - 1) * 2; // max span

  for (i = 0; i < numRows; i++) {
    j = i; // first letter of each row
    up = 1;
    while (j < len) {
      p[k++] = s[j];
      if (i == 0 || i == numRows - 1) {
        j += step; // full span
      } else if (up) {
        j += step - i * 2; // full span - offset
        up = 0;
      } else {
        j += i * 2; // offset
        up = 1;
      }
    }
  }
  p[k] = 0;
  return p;
}

class Solution {
public:
  string convert(string s, int numRows) {
    if (numRows == 1) return s;
    int n = s.size();
    int cycle = 2 * numRows - 2;
    string ret;
    for (int i = 0; i < numRows; i++) {
      for (int j = 0; i + j < n; j += cycle) {
        ret += s[i + j];
        if (i != 0 && i != numRows - 1 && j + cycle - i < n) {
          ret += s[j + cycle - i];
        }
      }
    }
    return ret;
  }
};

func convert(s string, numRows int) (ret string) {
	if numRows == 1 {
		return s
	}
	var n = len(s)
	var cycleLen = 2*numRows - 2
	for i := 0; i < numRows; i++ {
		for j := 0; i+j < n; j += cycleLen {
			ret += s[j+i : j+i+1]
			if i != 0 && i != numRows-1 && j+cycleLen-i < n {
				ret += s[j+cycleLen-i : j+cycleLen-i+1]
			}
		}
	}
	return ret
}

class Solution {
  public String convert(String s, int numRows) {
    if (numRows == 1) {
      return s;
    }
    int n = s.length();
    int cycle = 2 * numRows - 2;
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < numRows; i++) {
      for (int j = 0; i + j < n; j += cycle) {
        sb.append(s.charAt(i + j));
        if (i != 0 && i != numRows - 1 && j + cycle - i < n) {
          sb.append(s.charAt(j + cycle - i));
        }
      }
    }
    return sb.toString();
  }
}

class Solution:
    def convert(self, s: str, numRows: int) -> str:
        if numRows == 1:
            return s
        n = len(s)
        cycle = 2 * numRows - 2
        ret = []
        for i in range(numRows):
            j = 0
            while i + j < n:
                ret.append(s[i + j])
                if i != 0 and i != numRows - 1 and j + cycle - i < n:
                    ret.append(s[j + cycle - i])
                j += cycle
        return "".join(ret)

impl Solution {
  pub fn convert(s: String, num_rows: i32) -> String {
    let num_rows = num_rows as usize;
    if num_rows == 1 {
      return s;
    }
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let cycle = 2 * num_rows - 2;
    let mut ret = String::new();

    for i in 0..num_rows {
      let mut j = 0usize;
      while i + j < n {
        ret.push(chars[i + j]);
        if i != 0 && i != num_rows - 1 && j + cycle - i < n {
          ret.push(chars[j + cycle - i]);
        }
        j += cycle;
      }
    }

    ret
  }
}

const convert = (s: string, numRows: number): string => {
  if (numRows === 1) return s;
  const n = s.length;
  const cycle = 2 * numRows - 2;
  let ret = '';

  for (let i = 0; i < numRows; i++) {
    for (let j = 0; i + j < n; j += cycle) {
      ret += s[i + j];
      if (i !== 0 && i !== numRows - 1 && j + cycle - i < n) {
        ret += s[j + cycle - i];
      }
    }
  }

  return ret;
};
